package main
const guiHTML = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Steam 收藏整理</title>
<style>
:root{--bg:#0f1720;--panel:#182431;--panel2:#213243;--line:#33495c;--text:#e9f0f5;--muted:#91a5b5;--blue:#5aa9e6;--green:#74d99b;--red:#ff8d8d;--gold:#f2c46d}
*{box-sizing:border-box}body{margin:0;background:linear-gradient(145deg,#0d151e,#152333 60%,#10202d);color:var(--text);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1540px;margin:auto;padding:24px}h1{margin:0 0 5px;font-size:26px}h2{font-size:16px;margin:0 0 12px}p{color:var(--muted);line-height:1.55}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:18px}.status{padding:8px 12px;border-radius:20px;background:#223746;color:var(--muted)}.ok{color:var(--green)}.bad{color:var(--red)}button{border:1px solid #4b7591;border-radius:6px;background:#1d6fa3;color:#fff;padding:8px 12px;margin:3px;cursor:pointer}button:hover{filter:brightness(1.15)}button.secondary{background:#263b4b;border-color:var(--line)}button.warn{background:#825127;border-color:#b67c3e}.toolbar,.panel{background:rgba(24,36,49,.94);border:1px solid var(--line);border-radius:9px;padding:14px;margin:12px 0}.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:4px}.layout{display:grid;grid-template-columns:260px minmax(500px,1fr) 330px;gap:12px;align-items:start}.panel.sticky{position:sticky;top:12px;max-height:calc(100vh - 24px);overflow:auto}.tree{max-height:64vh;overflow:auto}.tree button{display:block;width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid #263b4b;border-radius:0;color:var(--text);margin:0;padding:8px}.tree button.active{background:#28506c;color:#fff}.tree .count{float:right;color:var(--muted)}.tree .group{font-size:12px;color:var(--gold);padding:12px 5px 4px}.tree button .move{display:inline-block;width:auto;float:right;clear:none;padding:1px 5px;margin:0 0 0 3px;background:transparent;border:0;color:var(--muted)}input,select,textarea{width:100%;border:1px solid var(--line);border-radius:5px;background:#101a24;color:var(--text);padding:8px;font:inherit}input{margin-bottom:8px}textarea{min-height:120px;resize:vertical}.table-wrap{overflow:auto;max-height:65vh;border:1px solid var(--line);border-radius:6px}table{border-collapse:collapse;width:100%;min-width:740px}th,td{text-align:left;padding:9px;border-bottom:1px solid #283b4a;vertical-align:top}th{position:sticky;top:0;background:#203442;color:#b7d5e8}td small{display:block;color:var(--muted);margin-top:3px}.pill{display:inline-block;border:1px solid #4d687b;border-radius:12px;padding:2px 7px;margin:2px;color:#c6d9e5;font-size:12px}.price{color:var(--gold);white-space:nowrap}.free{color:var(--green)}.note{padding:10px;background:#20313c;border-left:3px solid var(--blue);color:#c6d9e5;line-height:1.5}.danger{border-left-color:var(--red)}.json{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;min-height:150px}.hidden{display:none}.subtle{font-size:12px;color:var(--muted)}#preview{white-space:pre-wrap;max-height:330px;overflow:auto;background:#0d151e;border-radius:5px;padding:10px;font:12px ui-monospace,monospace}.ai-prompt{min-height:180px}@media(max-width:1150px){.layout{grid-template-columns:220px minmax(450px,1fr)}.right{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr;gap:12px}.right .panel{margin:0}}@media(max-width:760px){main{padding:12px}.layout{display:block}.panel.sticky{position:static;max-height:none}.tree{max-height:260px}.right{display:block}.table-wrap{max-height:none}}
.collection-row{display:flex;align-items:center}.tree .collection-row>.move{width:26px;flex:0 0 26px;padding:6px 2px}.history-row{display:flex;gap:6px;align-items:center;border-bottom:1px solid var(--line);padding:8px 0}.history-row>button{width:auto}.history-row>button:first-child{text-align:left}input[type=checkbox]{width:18px;height:18px}.tree button .move{width:25px}.view-switch{display:flex;gap:8px;margin:10px 0}</style></head><body><main>
<div class="top"><div><h1>Steam 收藏整理</h1><div class="subtle">按收藏浏览和编辑 · 价格来自中国区 Steam 商店 · 规则 JSON 仅用于导入/导出</div></div><div id="status" class="status">正在读取 Steam…</div></div>
<div class="toolbar"><button onclick="showTab('library')" class="secondary">游戏库</button><button onclick="showTab('history')" class="secondary">历史 / 导入导出</button><button onclick="diagnostics()" class="connection-action">连接诊断</button><button onclick="restartSteam()" class="secondary connection-action">准备连接 Steam</button><button onclick="connect()" class="connection-action">重新读取 Steam</button><button onclick="preview()">生成预览</button><button onclick="apply()" class="warn">确认保存到 Steam</button><button onclick="quitTool()" class="secondary">退出工具</button></div>
<section id="diagnosticsPanel" class="panel hidden"><h2>连接诊断</h2><div id="diagnosticsResult"></div></section>
<div id="libraryView"><div class="layout"><aside class="panel sticky"><h2>收藏</h2><div class="note">动态收藏由你在 Steam 中创建和维护。程序只读取它们来计算重叠，不会自动创建、改名或修改动态规则。</div><div id="dynamicTree" class="tree"></div><div id="staticTree" class="tree"></div></aside>
<section class="panel"><div class="view-switch"><button class="secondary" onclick="browsingActual=true;selected='';renderAll()">Steam 当前收藏</button><button class="secondary" onclick="browsingActual=false;selected='';renderAll()">待保存方案</button></div><div class="toolbar" style="padding:0;border:0;background:none"><div style="flex:1"><h2 id="collectionTitle">全部游戏</h2><div id="collectionMeta" class="subtle"></div></div><button onclick="refreshPrices()" class="secondary">获取商店资料和价格</button></div><div class="toolbar"><input id="bulkTarget" list="bulkTargets" placeholder="输入或选择目标静态收藏"><datalist id="bulkTargets"></datalist><button onclick="applySelectedTarget()">应用到勾选游戏</button><button onclick="togglePageSelection()" class="secondary">勾选本页</button><button onclick="checkedGames.clear();renderGames()" class="secondary">清空勾选</button><button onclick="previewRemoval()" class="warn">移除选中的免费游戏</button><span id="selectionCount" class="subtle"></span></div><div class="toolbar"><select id="publisherFilter" style="flex:1" onchange="pageNo=0;renderGames()"><option value="">全部发行厂商</option></select><select id="gameSort" style="flex:1" onchange="pageNo=0;renderGames()"><option value="name">按名称</option><option value="recent">按最后游玩</option><option value="playtime">按游玩时长</option></select></div><input id="search" placeholder="搜索名称、AppID 或厂商" oninput="pageNo=0;renderGames()"><div class="table-wrap"><table><thead><tr><th>选择</th><th>游戏</th><th>目标收藏</th><th>发行厂商</th><th>最后游玩</th><th>游玩时长</th><th>中国区价格</th><th>状态</th></tr></thead><tbody id="games"></tbody></table></div><div class="toolbar"><button onclick="pageBy(-1)" class="secondary">上一页</button><span id="pageInfo" class="subtle"></span><button onclick="pageBy(1)" class="secondary">下一页</button></div></section>
<aside class="right">
<details class="panel" open><summary>AI 整理</summary><p class="subtle">分类提示词由你编写，AI 结果会先进入独立审核窗口。</p><input id="aiurl" placeholder="OpenAI 兼容地址，例如 https://api.example.com/v1"><input id="aikey" type="password" placeholder="API Key（仅本次运行内存）"><button onclick="models()">获取模型</button><select id="model"></select><textarea id="prompt" class="ai-prompt" placeholder="请填写自己的分类规则。例如：知名大作按系列归类，精品独立游戏单独收藏，其余按玩法分类。此处参考仅供修改。"></textarea><button onclick="suggest()">生成 AI 草稿并审核</button><div id="priceInfo" class="subtle"></div></details></aside></div>
<section class="panel"><h2>预览和执行日志</h2><div id="preview">尚未预览</div></section>
</div><section id="historyView" class="panel hidden"><h2>历史</h2><p class="subtle">仅在实际应用收藏修改前自动备份；读取、导入和预览不会产生历史。外置整理清单也在这里，删除只影响本机文件。</p><input id="ruleFile" type="file" accept=".json,application/json"><button onclick="importRules()" class="secondary">导入 JSON 到审核窗口</button><button onclick="exportCurrent()" class="secondary">导出当前方案 JSON</button><button onclick="exportLibrary()" class="secondary">导出游戏列表和收藏</button><button onclick="refreshHistory()" class="secondary">刷新历史</button><div id="historyList" class="tree"></div></section>
</main><script>
let browsingActual=true; let stateData=null, selected='', visibleGames=[], pageNo=0, pageSize=50, reviewWindow=null, pendingDraft=null;
async function api(path,body){let r=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});return await r.json()}
function status(msg,ok=true){let el=document.querySelector('#status');el.textContent=msg;el.className='status '+(ok?'ok':'bad')}
function nameList(){if(browsingActual&&stateData.snapshot?.collections){let names=stateData.snapshot.collections.filter(c=>!c.dynamic&&(!c.system||c.id==='favorite')).map(c=>c.name),order=stateData.manifest.collection_order||[];return [...order.filter(n=>names.includes(n)),...names.filter(n=>!order.includes(n))]}let order=stateData.manifest.collection_order||[];let names=[...new Set((stateData.manifest.games||[]).flatMap(g=>planTargets(g)))];return [...order.filter(n=>names.includes(n)),...names.filter(n=>!order.includes(n)).sort()]}
function dynamicCollections(){return (stateData.snapshot?.collections||[]).filter(c=>c.dynamic&&!c.system)}
function isDynamic(n){return dynamicCollections().some(c=>c.name===n)}
function renderTree(){
let dyn=document.querySelector('#dynamicTree'),stat=document.querySelector('#staticTree');dyn.innerHTML='';
function add(label,key,count){let b=document.createElement('button');b.textContent=label+(count===undefined?'':' · '+count);b.className=selected===key?'active':'';b.onclick=()=>{selected=key;pageNo=0;renderAll()};dyn.appendChild(b)}
add('全部游戏','');add('未分类','@uncategorized',uncategorizedIDs().size);add('无静态收藏','@no-static',noStaticIDs().size);
for(let c of dynamicCollections())add('◈ '+c.name,c.name,(c.appids||[]).length);
stat.innerHTML='<div class="group">静态收藏 · ↑↓调整显示和处理顺序</div>';let names=nameList().filter(n=>n!=='未分类');
for(let [i,n] of names.entries()){let row=document.createElement('div');row.className='collection-row';let b=document.createElement('button');b.style.flex='1';b.className=selected===n?'active':'';let count=browsingActual?((stateData.snapshot?.collections||[]).find(c=>c.name===n)?.appids||[]).length:(planCounts.get(n)||0);b.textContent=n+' · '+count;b.onclick=()=>{selected=n;pageNo=0;renderAll()};let up=document.createElement('button'),dn=document.createElement('button');up.textContent='↑';dn.textContent='↓';up.title='上移';dn.title='下移';up.className=dn.className='move';up.onclick=()=>moveCollection(i,-1);dn.onclick=()=>moveCollection(i,1);row.append(b,up,dn);stat.appendChild(row)}}
function noStaticIDs(){let ids=new Set((stateData.snapshot?.apps||[]).map(a=>a.appid));if(!browsingActual){for(let g of stateData.manifest.games)if(planTargets(g).length)ids.delete(g.appid);return ids}for(let c of stateData.snapshot?.collections||[])if(!c.dynamic&&(!c.system||c.id==='favorite'))for(let id of c.appids||[])ids.delete(id);return ids}
function uncategorizedIDs(){if(browsingActual){let c=(stateData.snapshot?.collections||[]).find(c=>c.id==='uncategorized');if(c)return new Set(c.appids||[])}let ids=noStaticIDs();for(let c of dynamicCollections())for(let id of c.appids||[])ids.delete(id);return ids}
function moveCollection(i,d){let a=nameList(),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];browsingActual=false;stateData.manifest.collection_order=a;renderAll();saveManifest(false)}
let planMemberships=new Map(),planCounts=new Map(),ruleIndex=new Map();
function indexPlan(){planMemberships=new Map();planCounts=new Map();ruleIndex=new Map((stateData.manifest.games||[]).map(g=>[g.appid,g]));if(stateData.manifest.collection_state){for(let c of stateData.manifest.collection_state.collections||[])if(!c.dynamic&&(!c.system||c.id==='favorite')){planCounts.set(c.name,(c.appids||[]).length);for(let id of c.appids||[]){if(!planMemberships.has(id))planMemberships.set(id,[]);planMemberships.get(id).push(c.name)}}}else for(let g of stateData.manifest.games){let names=g.target&&g.target!=='未分类'?[g.target]:[];planMemberships.set(g.appid,names);for(let n of names)planCounts.set(n,(planCounts.get(n)||0)+1)}}
function planTargets(g){return planMemberships.get(g.appid)||[]}
function renderAll(){indexPlan();renderTree();renderPublisherFilter();renderGames()}
let checkedGames=new Set(),removalPlan=null;
function publisherNames(g){let p=stateData.prices?.[g.appid];return p?.publishers?.length?p.publishers:(g.publishers||ruleIndex.get(g.appid)?.publishers||[])}
function renderPublisherFilter(){let el=document.querySelector('#publisherFilter');if(!el)return;let selectedPublisher=el.value,names=[...new Set(stateData.manifest.games.flatMap(publisherNames))].sort((a,b)=>a.localeCompare(b));el.innerHTML='<option value="">全部发行厂商</option><option value="@unknown">厂商待查询</option>'+names.map(n=>'<option value="'+esc(n)+'">'+esc(n)+'</option>').join('');if([...el.options].some(x=>x.value===selectedPublisher))el.value=selectedPublisher}
function playedText(t){return t>0?new Date(t*1000).toLocaleString():'无记录'}
function durationText(n){return n===undefined||n===null?'未提供':n>=60?(n/60).toFixed(1)+' 小时':n+' 分钟'}
function updateSelectionCount(){document.querySelector('#selectionCount').textContent='已选 '+checkedGames.size+' 款（跨页保留）'}
function priceText(p){if(!p)return '<span class="subtle">未查询</span>';if(p.error)return '<span class="subtle">待核实</span>';if(p.free)return '<span class="free">免费</span>';if(p.final_cny)return '<span class="price">¥'+p.final_cny.toFixed(2)+(p.discount_percent?' (-'+p.discount_percent+'%)':'')+'</span>';return '<span class="subtle">无报价</span>'}
function renderGames(){
if(!stateData)return;let q=(document.querySelector('#search').value||'').toLowerCase(),dynamic=isDynamic(selected),actual=browsingActual,appMap=new Map((stateData.snapshot?.apps||[]).map(a=>[a.appid,a])),members=new Set(((stateData.snapshot?.collections||[]).find(c=>c.name===selected)||{}).appids||[]);
if(selected==='@uncategorized')members=uncategorizedIDs();if(selected==='@no-static')members=noStaticIDs();
let source=actual?(stateData.snapshot?.apps||[]).map(a=>({...a,target:(stateData.snapshot.collections||[]).filter(c=>!c.dynamic&&(!c.system||c.id==='favorite')&&(c.appids||[]).includes(a.appid)).map(c=>c.name).join('；')||'未分类'})):stateData.manifest.games;
let pub=document.querySelector('#publisherFilter')?.value||'',sort=document.querySelector('#gameSort')?.value||'name';
let gs=source.filter(g=>(!selected||selected.startsWith('@')||dynamic||actual?(!selected||members.has(g.appid)):planTargets(g).includes(selected))&&((g.name+' '+g.appid+' '+publisherNames(g).join(' ')).toLowerCase().includes(q))&&(!pub||(pub==='@unknown'?!publisherNames(g).length:publisherNames(g).includes(pub))));
if(sort==='recent')gs.sort((a,b)=>(appMap.get(b.appid)?.last_played||0)-(appMap.get(a.appid)?.last_played||0));else if(sort==='playtime')gs.sort((a,b)=>(appMap.get(b.appid)?.playtime_minutes??-1)-(appMap.get(a.appid)?.playtime_minutes??-1));else gs.sort((a,b)=>a.name.localeCompare(b.name));
visibleGames=gs;document.querySelector('#collectionTitle').textContent=selected==='@uncategorized'?'未分类':selected==='@no-static'?'无静态收藏':selected||'全部游戏';document.querySelector('#collectionMeta').textContent=gs.length+' 款 · '+(actual?'Steam 实际状态':'待保存方案')+(dynamic?' · 动态成员只读，可另加静态归属':'');
let names=nameList().filter(n=>!isDynamic(n));document.querySelector('#bulkTargets').innerHTML=['未分类',...names.filter(n=>n!=='未分类')].map(n=>'<option value="'+esc(n)+'">').join('');let totalPages=Math.max(1,Math.ceil(gs.length/pageSize));if(pageNo>=totalPages)pageNo=totalPages-1;
document.querySelector('#pageInfo').textContent='第 '+(pageNo+1)+' / '+totalPages+' 页 · 每页 '+pageSize+' 款';let page=gs.slice(pageNo*pageSize,(pageNo+1)*pageSize),body=document.querySelector('#games');body.innerHTML='';
for(let g of page){let tr=document.createElement('tr'),info=appMap.get(g.appid)||{},rule=ruleIndex.get(g.appid)||g,tags=[];if(rule.protect)tags.push('保护');if(rule.quality_indie)tags.push('精品');if(rule.low_value)tags.push('低价值');if(rule.free_candidate)tags.push('免费候选');tr.innerHTML='<td></td><td><b>'+esc(g.name)+'</b><small>AppID '+g.appid+(rule.reason?' · '+esc(rule.reason):'')+'</small></td><td>'+esc(actual?g.target:planTargets(g).join('；')||'未分类')+'</td><td>'+esc(publisherNames(g).join('；')||'待查询')+'</td><td>'+esc(playedText(info.last_played))+'</td><td>'+esc(durationText(info.playtime_minutes))+'</td><td>'+priceText((stateData.prices||{})[g.appid])+'</td><td>'+tags.map(x=>'<span class="pill">'+x+'</span>').join('')+'</td>';let cb=document.createElement('input');cb.type='checkbox';cb.dataset.appid=g.appid;cb.checked=checkedGames.has(g.appid);cb.onchange=()=>{if(cb.checked)checkedGames.add(g.appid);else checkedGames.delete(g.appid);updateSelectionCount()};tr.children[0].appendChild(cb);body.appendChild(tr)}updateSelectionCount()}
function pageBy(d){pageNo=Math.max(0,pageNo+d);renderGames()}
function togglePageSelection(){let boxes=[...document.querySelectorAll('#games input[type=checkbox]')],all=boxes.every(b=>b.checked);for(let b of boxes){b.checked=!all;if(all)checkedGames.delete(Number(b.dataset.appid));else checkedGames.add(Number(b.dataset.appid))}updateSelectionCount()}
async function applySelectedTarget(){let n=document.querySelector('#bulkTarget').value.trim();if(!n||isDynamic(n)){status('请输入静态收藏名称',false);return}let ids=new Set(checkedGames);if(!ids.size){status('请先勾选游戏',false);return}let before=JSON.parse(JSON.stringify(stateData.manifest)),m=stateData.manifest;if(m.collection_state){for(let c of m.collection_state.collections)if(!c.dynamic&&(!c.system||c.id==='favorite'))c.appids=(c.appids||[]).filter(id=>!ids.has(id));if(n!=='未分类'){let c=m.collection_state.collections.find(c=>!c.dynamic&&(!c.system||c.id==='favorite')&&c.name===n);if(!c){c={id:'manual-'+Date.now(),name:n,dynamic:false,system:false,editable:true,deletable:true,appids:[]};m.collection_state.collections.push(c)}c.appids=[...new Set([...c.appids,...ids])]}}for(let g of m.games)if(ids.has(g.appid)){g.target=n;g.priority=6;g.dynamic_only_if_matched=false}let x=await saveManifest(false);if(!x.ok){stateData.manifest=before;status(x.error,false);return}browsingActual=false;checkedGames.clear();renderAll();status('已调整 '+ids.size+' 款待保存目标，请预览确认；动态收藏保持不变',true)}
function esc(x){return String(x).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\\':'&#92;','"':'&quot;'}[c]))}
async function saveManifest(show=true){stateData.manifest.game_count=stateData.manifest.games.length;let x=await api('/api/config',stateData.manifest);if(show)status(x.ok?'规则已保存':'规则保存失败',x.ok);return x}
async function loadState(){stateData=await api('/api/state');selected='';renderAll();status(stateData.connected?'Steam 已读取 · '+stateData.snapshot.apps.length+' 款':(stateData.startup_done?'未连接：'+(stateData.startup_error||'请使用准备连接 Steam，再重新读取'):'正在尝试读取 Steam…'),!!stateData.connected);let historyHeading=document.querySelector('#historyView h2');historyHeading.textContent='历史 · '+stateData.history_dir;historyHeading.style.overflowWrap='anywhere';refreshHistory()}
let connectionBusy=false;
function setConnectionBusy(busy){connectionBusy=busy;document.querySelectorAll('.connection-action').forEach(b=>b.disabled=busy)}
async function diagnostics(){if(connectionBusy)return;setConnectionBusy(true);status('正在检查 Steam 连接…');try{let x=await api('/api/diagnostics',{});document.querySelector('#diagnosticsPanel').classList.remove('hidden');document.querySelector('#diagnosticsResult').innerHTML=(x.steps||[]).map(s=>'<p class="'+(s.ok?'ok':'bad')+'"><b>'+esc(s.name)+' · '+(s.ok?'通过':'未通过')+'</b><br>'+esc(s.detail)+'</p>').join('');status(x.ok?'连接诊断通过':'连接诊断发现问题，请查看结果',x.ok)}catch(e){status('诊断失败：'+e.message,false)}finally{setConnectionBusy(false)}}
async function restartSteam(){if(connectionBusy||!confirm('请先退出正在运行的游戏。Steam 将正常退出并重新启动调试入口。'))return;setConnectionBusy(true);status('正在重启 Steam 并读取游戏库，请等待…');try{let x=await api('/api/restart-steam',{});if(x.ok)browsingActual=true;await loadState();status(x.ok?'Steam 已重启并读取 · '+x.apps+' 款':'连接失败：'+x.error,x.ok)}catch(e){status('连接失败：'+e.message,false)}finally{setConnectionBusy(false)}}
async function connect(){if(connectionBusy)return;setConnectionBusy(true);status('正在读取 Steam…');try{let x=await api('/api/connect',{});if(x.ok)browsingActual=true;await loadState();status(x.ok?'Steam 已连接 · '+x.apps+' 款':'连接失败：'+x.error,x.ok)}catch(e){status('连接失败：'+e.message,false)}finally{setConnectionBusy(false)}}
async function previewRemoval(){
if(connectionBusy)return;if(!checkedGames.size)return status('请先勾选要检查的免费游戏',false);if(checkedGames.size>50)return status('每批最多检查 50 款，请减少勾选数量',false);
let dialog=document.querySelector('#removalDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='removalDialog';dialog.style.cssText='width:min(960px,95vw);max-height:85vh;overflow:auto;background:#182431;color:#e9f0f5;border:1px solid #4b7591;border-radius:10px;padding:24px';dialog.innerHTML='<h2>批量移除免费游戏 · 先检查</h2><p>移除的是账号免费许可证，不是卸载文件。只执行下表通过检查的游戏；已有游玩记录、保护游戏、收费/锁区/下架、从属内容均跳过。不会编辑动态收藏或调用卸载向导。</p><div id="removalRows"></div><p id="removalMessage"></p><button id="removalConfirm" onclick="confirmRemoval()" class="warn" disabled>确认移除通过检查的游戏</button><button class="secondary" onclick="document.querySelector(\'#removalDialog\').close()">关闭</button>';document.body.appendChild(dialog)}
removalPlan=null;dialog.showModal();document.querySelector('#removalRows').textContent='正在核实当前中国区商店、最后游玩记录和 Steam 原生免费许可证…';document.querySelector('#removalMessage').textContent='';document.querySelector('#removalConfirm').disabled=true;setConnectionBusy(true);
try{let x=await api('/api/removal/preview',{appids:[...checkedGames]});if(!x.ok){document.querySelector('#removalRows').textContent=x.error;return}removalPlan=x.plan;let count=x.plan.items.filter(v=>v.eligible).length;document.querySelector('#removalRows').innerHTML='<table><thead><tr><th>游戏</th><th>检查结果</th><th>说明</th></tr></thead><tbody>'+x.plan.items.map(v=>'<tr><td>'+esc(v.name)+'<small>AppID '+v.appid+'</small></td><td class="'+(v.eligible?'ok':'bad')+'">'+(v.eligible?'可移除':'跳过')+'</td><td>'+esc(v.reason)+'</td></tr>').join('')+'</tbody></table>';document.querySelector('#removalMessage').textContent=count+' 款通过检查。确认后会再次核验；本次检查无法保证未来是否收费或下架。';document.querySelector('#removalConfirm').disabled=!count}catch(e){document.querySelector('#removalRows').textContent='检查失败：'+e.message}finally{setConnectionBusy(false)}}
async function confirmRemoval(){if(!removalPlan||connectionBusy)return;let count=removalPlan.items.filter(v=>v.eligible).length;if(!confirm('确认从账号移除 '+count+' 款通过检查的免费游戏许可证？如需再次游玩，要重新获取。'))return;setConnectionBusy(true);document.querySelector('#removalConfirm').disabled=true;document.querySelector('#removalMessage').textContent='正在重新核验并逐项执行，请勿切换账号或关闭工具…';let token=removalPlan.token;removalPlan=null;try{let x=await api('/api/removal/apply',{token,confirm:'REMOVE'});let lines=(x.results||[]).map(v=>v.name+'：'+v.detail);document.querySelector('#removalMessage').textContent=(x.ok?'本批已完成':'已停止：'+x.error)+(lines.length?'\n'+lines.join('\n'):'');document.querySelector('#removalMessage').style.whiteSpace='pre-wrap';for(let v of x.results||[])if(v.status==='removed')checkedGames.delete(v.appid);updateSelectionCount();status(x.ok?'移除请求已由 Steam 确认，请重新读取游戏库':x.error,x.ok)}catch(e){document.querySelector('#removalMessage').textContent='连接中断，结果未确认。请重新读取 Steam 后核实，避免直接重复操作：'+e.message}finally{setConnectionBusy(false)}}
async function preview(){let x=await api('/api/preview',{});status(x.ok?'预览完成':'预览被阻止：'+x.error,x.ok);renderPreview(x.preview)}
function renderPreview(p){let el=document.querySelector('#preview');if(!p){el.textContent='没有预览结果';return}let counts={};for(let t of Object.values(p.effective_targets||{}))counts[t||'未分类（可保留动态）']=(counts[t||'未分类（可保留动态）']||0)+1;let rows=Object.entries(counts).sort((a,b)=>a[0].localeCompare(b[0])).map(([n,c])=>'<tr><td>'+esc(n)+'</td><td>'+c+'</td></tr>').join('');let actions=(p.actions||[]).map(a=>'<tr><td>'+esc(a.phase)+'</td><td>'+esc(a.name)+'</td><td>'+((a.before||[]).length)+' → '+((a.after||[]).length)+'</td></tr>').join('');let blocked=(p.blocked||[]).map(x=>'<p class="bad">'+esc(x)+'</p>').join('');el.innerHTML='<div><b>账号：</b>'+esc(p.account||'未知')+'　<b>清单匹配：</b>'+p.found_total+' / '+p.manifest_count+'　<b>本次处理：</b>'+p.scope_count+'　<b>未找到：</b>'+((p.missing||[]).length)+'</div>'+blocked+'<h3>静态目标收藏</h3><table><thead><tr><th>收藏</th><th>游戏数</th></tr></thead><tbody>'+rows+'</tbody></table><h3>待执行变更</h3><table><thead><tr><th>操作</th><th>收藏</th><th>成员数</th></tr></thead><tbody>'+actions+'</tbody></table><p class="subtle">动态收藏只读取，不在变更列表中。正式保存前会再次核对 Steam 当前状态并备份。</p>'}
async function apply(){if(!confirm('请确认已在预览中检查动态提示、数量和目标收藏。保存会修改 Steam 收藏并先写入备份。'))return;let x=await api('/api/apply',{confirm:'APPLY'});if(x.ok){browsingActual=true;await loadState()}status(x.ok?'已保存：'+x.backup:x.error,x.ok)}
async function quitTool(){if(!confirm('关闭 Steam 收藏整理工具？'))return;await api('/api/quit',{});status('工具已退出',true)}
async function refreshPrices(){let ids=visibleGames.map(g=>g.appid);if(!ids.length){status('当前列表没有游戏',false);return}status('正在获取 '+Math.min(ids.length,500)+' 款中国区价格…',true);let x=await api('/api/prices/refresh',{appids:ids});if(x.ok){stateData.prices=x.prices;renderAll();document.querySelector('#priceInfo').textContent='已缓存 '+x.count+' 款；查询时间 '+new Date().toLocaleString()}status(x.ok?'价格已更新':x.error,x.ok)}
async function models(){let x=await api('/api/ai/models',{url:document.querySelector('#aiurl').value,key:document.querySelector('#aikey').value});status(x.ok?'模型已载入':'模型获取失败：'+x.error,x.ok);if(x.ok){let sel=document.querySelector('#model');sel.innerHTML='';for(let m of (x.data.data||[])){let o=document.createElement('option');o.value=m.id;o.textContent=m.id;sel.appendChild(o)}}}
function openReviewWindow(){if(!window.__desktopShell)return window.open('/review?wait=1','steam-classification-review','width=1100,height=850,resizable=yes,scrollbars=yes');let overlay=document.getElementById('reviewOverlay');if(!overlay){overlay=document.createElement('div');overlay.id='reviewOverlay';overlay.style.cssText='position:fixed;inset:0;z-index:9999;display:flex;padding:18px;background:rgba(8,14,21,.88)';let box=document.createElement('div');box.style.cssText='flex:1;display:flex;flex-direction:column;min-width:0;background:#101923;border:1px solid #344b5c;border-radius:10px;overflow:hidden';let bar=document.createElement('div');bar.style.cssText='display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 12px;background:#1b2a38;border-bottom:1px solid #2c4050';let title=document.createElement('span');title.textContent='收藏方案审核';title.style.fontWeight='600';let close=document.createElement('button');close.className='secondary';close.textContent='关闭审核窗口';close.onclick=closeReviewPane;bar.appendChild(title);bar.appendChild(close);let frame=document.createElement('iframe');frame.id='reviewFrame';frame.title='收藏方案审核';frame.style.cssText='flex:1;border:0;background:#101923';box.appendChild(bar);box.appendChild(frame);overlay.appendChild(box);document.body.appendChild(overlay)}let frame=document.getElementById('reviewFrame');frame.src='/review?wait=1';return frame.contentWindow}
function closeReviewPane(){let overlay=document.getElementById('reviewOverlay');if(overlay)overlay.remove();reviewWindow=null}
function openReview(reset=false){if(reset){pendingDraft=null;reviewWindow=openReviewWindow();return reviewWindow}if(!reviewWindow||reviewWindow.closed)reviewWindow=openReviewWindow();return reviewWindow}
async function draftReview(m,kind,source){let normalized=await api('/api/import/normalize',m);if(!normalized.ok){status(normalized.error,false);return}m=normalized.manifest;let staged=await api('/api/draft',{manifest:m,kind,source});if(!staged.ok){status(staged.error,false);return}pendingDraft={type:'steam-draft',manifest:m,kind,source};let w=openReview();if(!w){status('审核窗口被浏览器拦截，请允许本地弹窗后重试',false);return}if(w.location.origin===location.origin&&w.document.readyState==='complete')w.postMessage(pendingDraft,location.origin)}
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;if(e.data?.type==='review-close'){closeReviewPane();return}if(e.data?.type==='review-ready'&&pendingDraft&&reviewWindow&&!reviewWindow.closed)reviewWindow.postMessage(pendingDraft,location.origin);if(e.data?.type==='draft-accepted'){pendingDraft=null;browsingActual=false;loadState();status('草稿已接受并载入主表',true)}if(e.data?.type==='draft-rejected'){pendingDraft=null;status('已拒绝草稿，主表未改变',true)}})
async function suggest(){let p=document.querySelector('#prompt').value.trim();if(!p){status('请先填写自己的提示词',false);return}if(!stateData.manifest.games.length){status('请先读取 Steam 库',false);return}let w=openReview(true);if(!w){status('请允许本地审核弹窗',false);return}let games=stateData.manifest.games,targets=nameList().filter(n=>!isDynamic(n)),apps=new Map((stateData.snapshot?.apps||[]).map(a=>[a.appid,a])),all=[];for(let i=0;i<games.length;i+=80){status('AI 建议 '+Math.min(i+80,games.length)+' / '+games.length,true);let batch=games.slice(i,i+80).map(g=>({...g,price:(stateData.prices||{})[g.appid]||null,last_played:(apps.get(g.appid)||{}).last_played||0}));let x=await api('/api/ai/suggest',{url:document.querySelector('#aiurl').value,key:document.querySelector('#aikey').value,model:document.querySelector('#model').value,prompt:p,games:batch,targets});if(!x.ok){status(x.error,false);return}try{let raw=x.response.choices?.[0]?.message?.content||'';raw=raw.replace(/^\x60\x60\x60json\s*/,'').replace(/\s*\x60\x60\x60$/,'');let parsed=JSON.parse(raw);all.push(...(Array.isArray(parsed)?parsed:(parsed.suggestions||[])))}catch(e){status('AI 返回不是可解析 JSON',false);return}}let draft=JSON.parse(JSON.stringify(stateData.manifest));delete draft.collection_state;let by=new Map(all.map(v=>[Number(v.appid),v]));for(let g of draft.games){let v=by.get(g.appid);if(v&&typeof v.target==='string'&&v.target.trim()&&!isDynamic(v.target)){g.target=v.target.trim();g.priority=6;g.dynamic_only_if_matched=false;g.reason='AI 建议（待审核）：'+(v.reason||'')}}await draftReview(draft,'AI 分类建议','用户提示词');status('AI 草稿已打开独立审核窗口',true)}
async function importRules(){let f=document.querySelector('#ruleFile').files[0];if(!f){status('请选择 JSON 文件',false);return}let w=openReview(true);if(!w){status('请允许本地审核弹窗',false);return}try{let m=JSON.parse(await f.text());await draftReview(m,'JSON 分类导入',f.name)}catch(e){status('JSON 解析失败：'+e.message,false)}}
async function exportCurrent(){if(!stateData.manifest.game_count){status('请先读取 Steam 或接受导入方案',false);return}let x=await api('/api/save-json',{name:'classification-current.json',data:stateData.manifest});status(x.ok?'已保存到 '+x.path+'（没有增加历史备份）':x.error,x.ok)}
async function exportLibrary(){let x=await api('/api/export',{});if(x.ok){refreshHistory();status('游戏列表和收藏已导出并写入历史：'+x.dir,true)}else status(x.error,false)}
async function refreshHistory(){let x=await api('/api/history');let el=document.querySelector('#historyList');el.innerHTML='';if(!x.ok){el.textContent=x.error;return}for(let item of x.items||[]){let row=document.createElement('div');row.className='history-row';let b=document.createElement('button');b.className='secondary';b.style.flex='1';b.textContent=item.title+' · '+new Date(item.created_at).toLocaleString();b.onclick=async()=>{openReview(true);let y=await api('/api/history/read',{id:item.id});if(y.ok)await draftReview(y.data,'历史导入审核',item.title);else status(y.error,false)};let ex=document.createElement('button');ex.textContent='导出 JSON';ex.className='secondary';ex.onclick=async()=>{let y=await api('/api/history/read',{id:item.id});if(!y.ok){status(y.error,false);return}let nm=(item.path||'').split(/[\\/]/).pop()||'history.json',z=await api('/api/save-json',{name:nm,data:y.data});status(z.ok?'已保存到 '+z.path:z.error,z.ok)};let d=document.createElement('button');d.textContent='删除';d.className='secondary';d.onclick=async()=>{let y=await api('/api/history/delete',{id:item.id});if(!y.ok)status(y.error,false);refreshHistory()};row.append(b,ex,d);el.appendChild(row)}}
function showTab(tab){document.querySelector('#libraryView').classList.toggle('hidden',tab!=='library');document.querySelector('#historyView').classList.toggle('hidden',tab!=='history');if(tab==='history')refreshHistory()}
async function startup(){await loadState();while(!stateData.startup_done&&!stateData.connected){await new Promise(resolve=>setTimeout(resolve,1000));await loadState()}}
startup();
</script></body></html>`
